func (t IPItem) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t IPItem) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "cidr":
		return t.AsIPItemCIDR()
	case "dns":
		return t.AsIPItemDNS()
	case "host":
		return t.AsIPItemHost()
	case "ip":
		return t.AsIPItemIP()
	case "set":
		return t.AsIPItemSet()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t IPItem) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *IPItem) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAuditEvents Audit log, newest first
	// (GET /api/activity/audit)
	ListAuditEvents(w http.ResponseWriter, r *http.Request, params ListAuditEventsParams)
	// ListJobs Background jobs with last and next run (invariant 15)
	// (GET /api/activity/jobs)
	ListJobs(w http.ResponseWriter, r *http.Request)
	// ListLogLines Recent log lines (already redacted), after a sequence number
	// (GET /api/activity/logs)
	ListLogLines(w http.ResponseWriter, r *http.Request, params ListLogLinesParams)
	// LookupAddress Every set that contains the address, with the nesting path to the element that holds it
	// (GET /api/addresses/{address})
	LookupAddress(w http.ResponseWriter, r *http.Request, address string)
	// BootstrapLogin Sign in with the one-time bootstrap credentials (private networks only, before setup completes)
	// (POST /api/auth/bootstrap/login)
	BootstrapLogin(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current session, then clear the cookie
	// (POST /api/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ListPasskeys Registered passkeys
	// (GET /api/auth/passkeys)
	ListPasskeys(w http.ResponseWriter, r *http.Request)
	// PasskeyLoginOptions Start a passkey sign-in
	// (POST /api/auth/passkeys/login/options)
	PasskeyLoginOptions(w http.ResponseWriter, r *http.Request)
	// PasskeyLoginVerify Finish a passkey sign-in; issues a session bound to this IP
	// (POST /api/auth/passkeys/login/verify)
	PasskeyLoginVerify(w http.ResponseWriter, r *http.Request)
	// PasskeyRegisterOptions Start adding another passkey
	// (POST /api/auth/passkeys/register/options)
	PasskeyRegisterOptions(w http.ResponseWriter, r *http.Request)
	// PasskeyRegisterVerify Finish adding another passkey
	// (POST /api/auth/passkeys/register/verify)
	PasskeyRegisterVerify(w http.ResponseWriter, r *http.Request)
	// DeletePasskey Delete a passkey (never the last one); revokes sessions signed in with it
	// (DELETE /api/auth/passkeys/{id})
	DeletePasskey(w http.ResponseWriter, r *http.Request, id string)
	// RenamePasskey Rename a passkey
	// (PATCH /api/auth/passkeys/{id})
	RenamePasskey(w http.ResponseWriter, r *http.Request, id string)
	// Reauth Finish a passkey reauthentication (valid five minutes)
	// (POST /api/auth/reauth)
	Reauth(w http.ResponseWriter, r *http.Request)
	// ReauthOptions Start a passkey reauthentication
	// (POST /api/auth/reauth/options)
	ReauthOptions(w http.ResponseWriter, r *http.Request)
	// RecoverLogin Open a recovery session from a `hashi admin recover` link (private networks, once, 15 minutes)
	// (POST /api/auth/recover)
	RecoverLogin(w http.ResponseWriter, r *http.Request)
	// RecoverPasskeyOptions Start registering a replacement passkey
	// (POST /api/auth/recover/passkey/options)
	RecoverPasskeyOptions(w http.ResponseWriter, r *http.Request)
	// RecoverPasskeyVerify Finish registering the replacement passkey; ends the recovery session
	// (POST /api/auth/recover/passkey/verify)
	RecoverPasskeyVerify(w http.ResponseWriter, r *http.Request)
	// GetAuthSession Current session (or none), setup state flag and the CSRF token
	// (GET /api/auth/session)
	GetAuthSession(w http.ResponseWriter, r *http.Request)
	// ListSessions Active admin sessions
	// (GET /api/auth/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeOtherSessions Revoke every session except the current one
	// (POST /api/auth/sessions/revoke-others)
	RevokeOtherSessions(w http.ResponseWriter, r *http.Request)
	// RevokeSession Revoke one session by its correlation ID
	// (DELETE /api/auth/sessions/{id})
	RevokeSession(w http.ResponseWriter, r *http.Request, id string)
	// ListCertificates Certificates with expiry, last renewal and per-host distribution
	// (GET /api/certificates)
	ListCertificates(w http.ResponseWriter, r *http.Request)
	// RenewCertificate Renew now — a low-risk certificates plan for this certificate, applied right away (takes about a minute)
	// (POST /api/certificates/{id}/renew)
	RenewCertificate(w http.ResponseWriter, r *http.Request, id string)
	// GetDNSImport Import table; rows without a decision are new since the last import
	// (GET /api/dns/import/{zoneId})
	GetDNSImport(w http.ResponseWriter, r *http.Request, zoneId string)
	// PutDNSImportDecisions Save import decisions; RRSets marked for prune go into a pending high-risk prune plan
	// (PUT /api/dns/import/{zoneId}/decisions)
	PutDNSImportDecisions(w http.ResponseWriter, r *http.Request, zoneId string)
	// PlanDNS Plan the zone's entries now ("Sync now"); low-risk plans apply
	// (POST /api/dns/plan)
	PlanDNS(w http.ResponseWriter, r *http.Request)
	// PlanDNSProbe Plan the write test (create, verify and delete a `_hashi-test` TXT); runs only after approval (invariant 4)
	// (POST /api/dns/probe)
	PlanDNSProbe(w http.ResponseWriter, r *http.Request)
	// PlanDNSPrune Plan the removal of every RRSet marked for prune on the import table (high risk, 03 §4)
	// (POST /api/dns/prune)
	PlanDNSPrune(w http.ResponseWriter, r *http.Request)
	// CreateDNSRecord Add a manual entry; plans it right away (low risk applies, 01 §5.4)
	// (POST /api/dns/records)
	CreateDNSRecord(w http.ResponseWriter, r *http.Request)
	// DeleteDNSRecord Remove an entry; the deletion at the provider is a high-risk plan awaiting approval
	// (DELETE /api/dns/records/{id})
	DeleteDNSRecord(w http.ResponseWriter, r *http.Request, id string)
	// UpdateDNSRecord Change a manual or imported entry's TTL, values and display fields; plans it right away
	// (PATCH /api/dns/records/{id})
	UpdateDNSRecord(w http.ResponseWriter, r *http.Request, id string)
	// ListDNSZones Managed zones with their refresh state
	// (GET /api/dns/zones)
	ListDNSZones(w http.ResponseWriter, r *http.Request)
	// RefreshDNSZone Read the zone from the provider now and replace the observed snapshot (read-only towards the provider)
	// (POST /api/dns/zones/{id}/refresh)
	RefreshDNSZone(w http.ResponseWriter, r *http.Request, id string)
	// ListDNSRRSets Observed RRSets of a zone with Hashi's ownership
	// (GET /api/dns/zones/{id}/rrsets)
	ListDNSRRSets(w http.ResponseWriter, r *http.Request, id string, params ListDNSRRSetsParams)
	// GetEdgeAuthForward Traefik forward auth for every edge service
	// (GET /api/edge-auth/forward)
	GetEdgeAuthForward(w http.ResponseWriter, r *http.Request)
	// GetFirewallBindings The IP sets bound to global firewall allow and block
	// (GET /api/firewall/bindings)
	GetFirewallBindings(w http.ResponseWriter, r *http.Request)
	// PutFirewallBindings Replace the global bindings and plan every managed host
	// (PUT /api/firewall/bindings)
	PutFirewallBindings(w http.ResponseWriter, r *http.Request)
	// ListFirewallHosts Every firewall host with its detected facts
	// (GET /api/firewall/hosts)
	ListFirewallHosts(w http.ResponseWriter, r *http.Request)
	// CreateFirewallHost Add a firewall host (validated right away when managed)
	// (POST /api/firewall/hosts)
	CreateFirewallHost(w http.ResponseWriter, r *http.Request)
	// DeleteFirewallHost Delete a host that nothing references (Hashi's table on it stays until removed by hand)
	// (DELETE /api/firewall/hosts/{id})
	DeleteFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// GetFirewallHost One firewall host
	// (GET /api/firewall/hosts/{id})
	GetFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// UpdateFirewallHost Change a host's settings (a changed SSH address or host key needs a new host)
	// (PUT /api/firewall/hosts/{id})
	UpdateFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// ConfirmFirewallHost Let Hashi manage the validated host's firewall (its own table only)
	// (POST /api/firewall/hosts/{id}/confirm)
	ConfirmFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// GetFirewallHostAccess The IP sets allowed to reach the host itself
	// (GET /api/firewall/hosts/{id}/host-access)
	GetFirewallHostAccess(w http.ResponseWriter, r *http.Request, id string)
	// PutFirewallHostAccess Replace the host's access sets and plan the host
	// (PUT /api/firewall/hosts/{id}/host-access)
	PutFirewallHostAccess(w http.ResponseWriter, r *http.Request, id string)
	// PlanFirewallHost Plan the host now; low-risk plans apply, high-risk ones wait on Pending changes
	// (POST /api/firewall/hosts/{id}/plan)
	PlanFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// GetFirewallRendered The table Hashi would load on the host now (libnftables JSON) and the folded counts
	// (GET /api/firewall/hosts/{id}/rendered)
	GetFirewallRendered(w http.ResponseWriter, r *http.Request, id string)
	// GetFirewallRuleset The host's ruleset read now over SSH (all tables, iptables and ipsets), and the one read at setup
	// (GET /api/firewall/hosts/{id}/ruleset)
	GetFirewallRuleset(w http.ResponseWriter, r *http.Request, id string)
	// GetFirewallTakeover What Hashi removes of the host's old firewall script
	// (GET /api/firewall/hosts/{id}/takeover)
	GetFirewallTakeover(w http.ResponseWriter, r *http.Request, id string)
	// PutFirewallTakeover Replace the takeover list and plan the host (05 §3.4)
	// (PUT /api/firewall/hosts/{id}/takeover)
	PutFirewallTakeover(w http.ResponseWriter, r *http.Request, id string)
	// ValidateFirewallHost Read the host again over SSH (read-only)
	// (POST /api/firewall/hosts/{id}/validate)
	ValidateFirewallHost(w http.ResponseWriter, r *http.Request, id string)
	// ScanFirewallHost Read a host's SSH key for the admin to compare (nothing is stored)
	// (POST /api/firewall/scan)
	ScanFirewallHost(w http.ResponseWriter, r *http.Request)
	// ListIPSets Every IP set with its last compile summary, system sets first
	// (GET /api/ip-sets)
	ListIPSets(w http.ResponseWriter, r *http.Request, params ListIPSetsParams)
	// CreateIPSet Add a user IP set (empty; add elements next)
	// (POST /api/ip-sets)
	CreateIPSet(w http.ResponseWriter, r *http.Request)
	// DeleteIPSet Delete a user set that nothing uses (409 lists what still uses it)
	// (DELETE /api/ip-sets/{id})
	DeleteIPSet(w http.ResponseWriter, r *http.Request, id string)
	// GetIPSet One IP set
	// (GET /api/ip-sets/{id})
	GetIPSet(w http.ResponseWriter, r *http.Request, id string)
	// UpdateIPSet Change a user set's slug, name and description
	// (PUT /api/ip-sets/{id})
	UpdateIPSet(w http.ResponseWriter, r *http.Request, id string)
	// GetIPSetConsumers What uses the set (parent sets, firewall bindings, DNS records, service targets)
	// (GET /api/ip-sets/{id}/consumers)
	GetIPSetConsumers(w http.ResponseWriter, r *http.Request, id string)
	// ListIPSetElements A set's own elements, filtered by address (containing), prefix (overlapping) or text
	// (GET /api/ip-sets/{id}/elements)
	ListIPSetElements(w http.ResponseWriter, r *http.Request, id string, params ListIPSetElementsParams)
	// AddIPSetElement Append an element to a user set (a set the firewall uses needs a fresh passkey confirmation, 02 §2)
	// (POST /api/ip-sets/{id}/elements)
	AddIPSetElement(w http.ResponseWriter, r *http.Request, id string)
	// DeleteIPSetElement Remove an element from a user set
	// (DELETE /api/ip-sets/{id}/elements/{elementId})
	DeleteIPSetElement(w http.ResponseWriter, r *http.Request, id string, elementId string)
	// UpdateIPSetElement Replace an element's item, note and expiry
	// (PATCH /api/ip-sets/{id}/elements/{elementId})
	UpdateIPSetElement(w http.ResponseWriter, r *http.Request, id string, elementId string)
	// GetIPSetResolved The set compiled now (prefixes merged per family, single addresses for target positions, problems)
	// (GET /api/ip-sets/{id}/resolved)
	GetIPSetResolved(w http.ResponseWriter, r *http.Request, id string, params GetIPSetResolvedParams)
	// ListServices Every service, system services first, with the reason when one cannot be rendered
	// (GET /api/services)
	ListServices(w http.ResponseWriter, r *http.Request)
	// CreateService Add a service; every Traefik host is planned right away (low-risk plans apply) and a needed certificate name is issued in the background
	// (POST /api/services)
	CreateService(w http.ResponseWriter, r *http.Request)
	// DeleteService Delete a user service and remove it from every Traefik host
	// (DELETE /api/services/{id})
	DeleteService(w http.ResponseWriter, r *http.Request, id string)
	// GetService One service
	// (GET /api/services/{id})
	GetService(w http.ResponseWriter, r *http.Request, id string)
	// UpdateService Replace a user service's fields and routes (system services change only through their owning setting)
	// (PUT /api/services/{id})
	UpdateService(w http.ResponseWriter, r *http.Request, id string)
	// DisableService Turn a user service off (it stays stored, absent from the rendered files)
	// (POST /api/services/{id}/disable)
	DisableService(w http.ResponseWriter, r *http.Request, id string)
	// GetServiceEffective The routers, middlewares and services Hashi renders for this service (rendered config preview)
	// (GET /api/services/{id}/effective)
	GetServiceEffective(w http.ResponseWriter, r *http.Request, id string)
	// EnableService Turn a user service on (it is rendered again)
	// (POST /api/services/{id}/enable)
	EnableService(w http.ResponseWriter, r *http.Request, id string)
	// GetSettings All settings categories
	// (GET /api/settings)
	GetSettings(w http.ResponseWriter, r *http.Request)

	// (GET /api/settings/appearance)
	GetAppearanceSettings(w http.ResponseWriter, r *http.Request)

	// (PUT /api/settings/appearance)
	PutAppearanceSettings(w http.ResponseWriter, r *http.Request)

	// (GET /api/settings/general)
	GetGeneralSettings(w http.ResponseWriter, r *http.Request)
	// PutGeneralSettings Save general settings; changing trusted proxies needs a recent passkey reauthentication
	// (PUT /api/settings/general)
	PutGeneralSettings(w http.ResponseWriter, r *http.Request)

	// (GET /api/settings/security)
	GetSecuritySettings(w http.ResponseWriter, r *http.Request)

	// (PUT /api/settings/security)
	PutSecuritySettings(w http.ResponseWriter, r *http.Request)
	// GetSetup Setup steps and their state
	// (GET /api/setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// PutSetupBaseSettings Step 2 — save and validate the base settings
	// (PUT /api/setup/base-settings)
	PutSetupBaseSettings(w http.ResponseWriter, r *http.Request)
	// PutSetupCertificates Step 4 — store the certificate provider and register the ACME account with the CA
	// (PUT /api/setup/certificates)
	PutSetupCertificates(w http.ResponseWriter, r *http.Request)
	// IssueSetupCertificates Step 4 — issue the root and wildcard certificate now (low-risk plan, applied right away; takes a minute)
	// (POST /api/setup/certificates/issue)
	IssueSetupCertificates(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Step 11 — finish setup; destroys the bootstrap credentials and signs out bootstrap sessions
	// (POST /api/setup/complete)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// GetSetupDNSImport Step 3 — import table of the managed zone
	// (GET /api/setup/dns/import)
	GetSetupDNSImport(w http.ResponseWriter, r *http.Request)
	// PutSetupDNSImport Step 3 — save import decisions (prune marks become a pending prune plan); completes the step
	// (PUT /api/setup/dns/import)
	PutSetupDNSImport(w http.ResponseWriter, r *http.Request)
	// PostSetupDNSProbe Step 3 — plan the write test (create and delete a `_hashi-test` TXT); nothing is written yet
	// (POST /api/setup/dns/probe)
	PostSetupDNSProbe(w http.ResponseWriter, r *http.Request)
	// RunSetupDNSProbe Step 3 — approve the shown probe plan and run it (invariant 4)
	// (POST /api/setup/dns/probe/{id}/run)
	RunSetupDNSProbe(w http.ResponseWriter, r *http.Request, id string)
	// PutSetupDNSProvider Step 3 — validate a DNS provider token read-only, pick the zone, store the first snapshot
	// (PUT /api/setup/dns/provider)
	PutSetupDNSProvider(w http.ResponseWriter, r *http.Request)
	// ConfirmSetupFirewall Step 6 — let Hashi manage the validated host's firewall (its table only); completes the step
	// (POST /api/setup/firewall/confirm)
	ConfirmSetupFirewall(w http.ResponseWriter, r *http.Request)
	// PutSetupFirewallHost Step 6 — save the first firewall host and validate it over SSH (read-only)
	// (PUT /api/setup/firewall/host)
	PutSetupFirewallHost(w http.ResponseWriter, r *http.Request)
	// PlanSetupFirewall Step 6 — plan Hashi's first firewall apply on the confirmed host; nothing is written yet
	// (POST /api/setup/firewall/plan)
	PlanSetupFirewall(w http.ResponseWriter, r *http.Request)
	// RunSetupFirewallPlan Step 6 — approve the shown firewall plan and run it under the rescue timer
	// (POST /api/setup/firewall/plan/{id}/run)
	RunSetupFirewallPlan(w http.ResponseWriter, r *http.Request, id string)
	// ScanSetupFirewallHost Step 6 — read the firewall host's SSH key for the admin to compare (nothing is stored)
	// (POST /api/setup/firewall/scan)
	ScanSetupFirewallHost(w http.ResponseWriter, r *http.Request)
	// ProveSetupHTTPS Step 8 — called from https://<admin domain> with the link's nonce; accepted only through Hashi-managed Traefik (edge token, Host, HTTPS). Completes the step and signs the browser in there with a new bootstrap session
	// (POST /api/setup/https/proof)
	ProveSetupHTTPS(w http.ResponseWriter, r *http.Request)
	// StartSetupHTTPS Step 8 — a one-time link (5 minutes) that opens setup on https://<admin domain>
	// (POST /api/setup/https/start)
	StartSetupHTTPS(w http.ResponseWriter, r *http.Request)
	// SetupPasskeyOptions Step 9 — start registering the first passkey
	// (POST /api/setup/passkey/options)
	SetupPasskeyOptions(w http.ResponseWriter, r *http.Request)
	// SetupPasskeyVerify Step 9 — finish registering the first passkey
	// (POST /api/setup/passkey/verify)
	SetupPasskeyVerify(w http.ResponseWriter, r *http.Request)
	// SetupRecoveryKey Step 9 — generate the recovery key (shown once)
	// (POST /api/setup/recovery-key)
	SetupRecoveryKey(w http.ResponseWriter, r *http.Request)
	// ConfirmRecoveryKey Step 9 — confirm the recovery key by re-entering its last group; runs a test unlock
	// (POST /api/setup/recovery-key/confirm)
	ConfirmRecoveryKey(w http.ResponseWriter, r *http.Request)
	// CreateSetupSystemService Step 7 — create the Hashi admin service from the base settings, issue a certificate that covers the admin domain when needed, and plan the Traefik host
	// (POST /api/setup/system-service)
	CreateSetupSystemService(w http.ResponseWriter, r *http.Request)
	// RunSetupSystemServicePlan Step 7 — approve the shown Traefik plan and run it; the step completes once the host serves the admin domain
	// (POST /api/setup/system-service/plan/{id}/run)
	RunSetupSystemServicePlan(w http.ResponseWriter, r *http.Request, id string)
	// ConfirmSetupTraefik Step 5 — let Hashi take over the validated host (existing config is backed up first); completes the step
	// (POST /api/setup/traefik/confirm)
	ConfirmSetupTraefik(w http.ResponseWriter, r *http.Request)
	// PutSetupTraefikConnection Step 5 — save the Traefik host with the confirmed host key and validate it over SSH
	// (PUT /api/setup/traefik/connection)
	PutSetupTraefikConnection(w http.ResponseWriter, r *http.Request)
	// SetupTraefikIdentity Step 5 — Hashi's SSH public key (created on first call) for the host's authorized_keys
	// (POST /api/setup/traefik/identity)
	SetupTraefikIdentity(w http.ResponseWriter, r *http.Request)
	// PlanSetupTraefik Step 5 — plan installing Traefik and Hashi's files on the confirmed host; nothing is written yet
	// (POST /api/setup/traefik/plan)
	PlanSetupTraefik(w http.ResponseWriter, r *http.Request)
	// RunSetupTraefikPlan Step 5 — approve the shown Traefik plan and run it
	// (POST /api/setup/traefik/plan/{id}/run)
	RunSetupTraefikPlan(w http.ResponseWriter, r *http.Request, id string)
	// ScanSetupTraefikHost Step 5 — read the host's SSH key for the admin to compare (nothing is stored)
	// (POST /api/setup/traefik/scan)
	ScanSetupTraefikHost(w http.ResponseWriter, r *http.Request)
	// ListSyncPlans Open plans (pending, approved, applying) with items, and recently finished ones
	// (GET /api/sync/plans)
	ListSyncPlans(w http.ResponseWriter, r *http.Request)
	// GetSyncPlan One plan with its exact items
	// (GET /api/sync/plans/{id})
	GetSyncPlan(w http.ResponseWriter, r *http.Request, id string)
	// ApplySyncPlan Apply an approved plan now; it is re-planned first and returns to approval if a new high-risk item appeared
	// (POST /api/sync/plans/{id}/apply)
	ApplySyncPlan(w http.ResponseWriter, r *http.Request, id string)
	// ApproveSyncPlan Approve a pending (high-risk) plan
	// (POST /api/sync/plans/{id}/approve)
	ApproveSyncPlan(w http.ResponseWriter, r *http.Request, id string)
	// DiscardSyncPlan Drop a pending or approved plan
	// (POST /api/sync/plans/{id}/discard)
	DiscardSyncPlan(w http.ResponseWriter, r *http.Request, id string)
	// ListTraefikConnections Traefik hosts with their state and applied files
	// (GET /api/traefik/connections)
	ListTraefikConnections(w http.ResponseWriter, r *http.Request)
	// PlanTraefikConnection Plan the host's install, files and certificates (low-risk plans apply right away)
	// (POST /api/traefik/connections/{id}/plan)
	PlanTraefikConnection(w http.ResponseWriter, r *http.Request, id string)
	// PlanTraefik Plan every Traefik host (low-risk plans apply right away)
	// (POST /api/traefik/plan)
	PlanTraefik(w http.ResponseWriter, r *http.Request)
	// GetVault Vault mode and state
	// (GET /api/vault)
	GetVault(w http.ResponseWriter, r *http.Request)
	// ListSecrets Stored secrets (metadata only, never values)
	// (GET /api/vault/secrets)
	ListSecrets(w http.ResponseWriter, r *http.Request)
	// RevealSecret Reveal one secret value (audited)
	// (POST /api/vault/secrets/{id}/reveal)
	RevealSecret(w http.ResponseWriter, r *http.Request, id string)
	// GetVersion Build version of the running binary
	// (GET /api/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
	// GetHealthz Process is alive
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// GetReadyz Dependencies are ready (database reachable, schema at head, not shutting down)
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
}

